  "witnessCode": "import {strict as assert} from 'node:assert';
import {test} from 'node:test';
import x from '../index.js';

test('stripWWW removes www. for single-label hostnames', () => {
  const result = x('www.a.com');
  assert.strictEqual(result, 'http://a.com');
  assert.doesNotInclude(result, 'www.');
});"
